public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field must be requested.');
            }
            if (String.isBlank(objectApiName)) {
                throw new SearchException('The object name is required.');
            }

            String normalizedObjectName = objectApiName.trim().toLowerCase();
            Schema.SObjectType objectType;
            for (String candidateName : Schema.getGlobalDescribe().keySet()) {
                if (candidateName.toLowerCase() == normalizedObjectName) {
                    objectType = Schema.getGlobalDescribe().get(candidateName);
                    break;
                }
            }
            if (objectType == null) {
                throw new SearchException('The object does not exist.');
            }

            Schema.DescribeSObjectResult objectDescribe = objectType.getDescribe();
            if (!objectDescribe.isAccessible()) {
                throw new SearchException('The running user cannot read the object.');
            }

            Map<String, Schema.SObjectField> fieldMapByNormalizedName =
                new Map<String, Schema.SObjectField>();
            for (String fieldName : objectDescribe.fields.getMap().keySet()) {
                fieldMapByNormalizedName.put(fieldName.toLowerCase(), objectDescribe.fields.getMap().get(fieldName));
            }

            Schema.SObjectField idToken = fieldMapByNormalizedName.get('id');
            if (idToken == null || !idToken.getDescribe().isAccessible()) {
                throw new SearchException('The running user cannot read the Id field.');
            }

            List<String> selectedFields = new List<String>{ idToken.getDescribe().getName() };
            Set<String> selectedFieldNames = new Set<String>{ 'id' };

            for (String requestedField : fields) {
                Schema.DescribeFieldResult fieldDescribe =
                    requireField(fieldMapByNormalizedName, requestedField);
                if (!fieldDescribe.isAccessible()) {
                    throw new SearchException('The running user cannot read a requested field.');
                }

                String canonicalName = fieldDescribe.getName();
                if (!selectedFieldNames.contains(canonicalName.toLowerCase())) {
                    selectedFields.add(canonicalName);
                    selectedFieldNames.add(canonicalName.toLowerCase());
                }
            }

            String canonicalOrderByField;
            if (!String.isBlank(orderByField)) {
                Schema.DescribeFieldResult orderDescribe =
                    requireField(fieldMapByNormalizedName, orderByField);
                if (!orderDescribe.isAccessible()) {
                    throw new SearchException('The running user cannot read the order-by field.');
                }
                if (!orderDescribe.isSortable()) {
                    throw new SearchException('The order-by field cannot be sorted.');
                }
                canonicalOrderByField = orderDescribe.getName();
            }

            List<String> whereConditions = new List<String>();
            Map<String, Object> bindValues = new Map<String, Object>();
            Integer bindIndex = 0;

            if (filters != null) {
                for (String filterName : filters.keySet()) {
                    Schema.DescribeFieldResult filterDescribe =
                        requireField(fieldMapByNormalizedName, filterName);
                    if (!filterDescribe.isAccessible()) {
                        throw new SearchException('The running user cannot read a filter field.');
                    }
                    if (!filterDescribe.isFilterable()) {
                        throw new SearchException('A filter field cannot be filtered.');
                    }

                    String bindName = 'filter' + String.valueOf(bindIndex);
                    whereConditions.add(filterDescribe.getName() + ' = :' + bindName);
                    bindValues.put(bindName, filters.get(filterName));
                    bindIndex++;
                }
            }

            String soql = 'SELECT ' + String.join(selectedFields, ', ') +
                ' FROM ' + objectDescribe.getName();

            if (!whereConditions.isEmpty()) {
                soql += ' WHERE ' + String.join(whereConditions, ' AND ');
            }
            if (canonicalOrderByField != null) {
                soql += ' ORDER BY ' + canonicalOrderByField + ' ASC';
            }
            soql += ' LIMIT ' + String.valueOf(maxRows);

            return Database.queryWithBinds(soql, bindValues, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('The search could not be completed.');
        }
    }

    private static Schema.DescribeFieldResult requireField(
        Map<String, Schema.SObjectField> fieldMapByNormalizedName,
        String fieldName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('A field name is required.');
        }

        Schema.SObjectField fieldToken =
            fieldMapByNormalizedName.get(fieldName.trim().toLowerCase());
        if (fieldToken == null) {
            throw new SearchException('A field does not exist on the object.');
        }
        return fieldToken.getDescribe();
    }
}
