public with sharing class ContactLookupAction {
    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;

        @InvocableVariable
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null) {
            return results;
        }

        List<String> normalizedEmails = new List<String>();
        Set<String> emailsToFind = new Set<String>();

        for (Request request : requests) {
            String normalizedEmail = request == null || request.email == null
                ? null
                : request.email.trim().toLowerCase();

            if (String.isBlank(normalizedEmail)) {
                normalizedEmail = null;
            } else {
                emailsToFind.add(normalizedEmail);
            }

            normalizedEmails.add(normalizedEmail);
        }

        Map<String, Id> earliestContactIdByEmail = new Map<String, Id>();

        if (!emailsToFind.isEmpty()) {
            for (Contact contact : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToFind
                ORDER BY CreatedDate ASC
            ]) {
                String normalizedContactEmail = contact.Email == null
                    ? null
                    : contact.Email.trim().toLowerCase();

                if (normalizedContactEmail != null
                    && !earliestContactIdByEmail.containsKey(normalizedContactEmail)) {
                    earliestContactIdByEmail.put(normalizedContactEmail, contact.Id);
                }
            }
        }

        for (String normalizedEmail : normalizedEmails) {
            Result result = new Result();
            Id matchedContactId = normalizedEmail == null
                ? null
                : earliestContactIdByEmail.get(normalizedEmail);

            result.contactId = matchedContactId;
            result.found = matchedContactId != null;
            results.add(result);
        }

        return results;
    }
}
