public class PicklistService {
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        String requestedObjectName = objectApiName.trim();
        String requestedFieldName = fieldApiName.trim();

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objectType;

        for (String candidateName : globalDescribe.keySet()) {
            if (candidateName.equalsIgnoreCase(requestedObjectName)) {
                objectType = globalDescribe.get(candidateName);
                break;
            }
        }

        if (objectType == null) {
            throw new PicklistServiceException(
                'Object does not exist: ' + requestedObjectName
            );
        }

        Map<String, Schema.SObjectField> fieldMap =
            objectType.getDescribe().fields.getMap();
        Schema.SObjectField fieldToken;

        for (String candidateName : fieldMap.keySet()) {
            if (candidateName.equalsIgnoreCase(requestedFieldName)) {
                fieldToken = fieldMap.get(candidateName);
                break;
            }
        }

        if (fieldToken == null) {
            throw new PicklistServiceException(
                'Field does not exist on object: ' + requestedFieldName
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.Picklist &&
            fieldType != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + requestedFieldName
            );
        }

        List<Option> options = new List<Option>();
