public with sharing class AccountScoringJob implements Queueable {
    private static final Integer BATCH_SIZE = 200;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds == null
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        Integer chainDepth = (accountIds.size() + BATCH_SIZE - 1) / BATCH_SIZE;

        // Developer Edition orgs have a default queueable chain depth of five.
        // Set the depth needed for the requested workload (up to 50,000 IDs).
        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = chainDepth;

        return System.enqueueJob(
            new AccountScoringJob(accountIds),
            options
        );
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer currentBatchSize = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> currentIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();

        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < currentBatchSize) {
                currentIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentIds
        ];

        for (Account account : accounts) {
            if (account.AnnualRevenue != null &&
                account.AnnualRevenue >= 1000000) {
                account.Rating = 'Hot';
            } else if (account.AnnualRevenue != null &&
                       account.AnnualRevenue >= 100000) {
                account.Rating = 'Warm';
            } else {
                account.Rating = 'Cold';
            }
        }

        if (!accounts.isEmpty()) {
            update accounts;
        }

        if (!remainingIds.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }
}
