public class ErpSyncFinalizer implements Finalizer {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : accountIds.clone();
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean succeeded = context.getResult() == ParentJobResult.SUCCESS;

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = attempt,
            Status__c = succeeded ? 'Success' : 'Failed'
        );

        if (!succeeded) {
            Exception jobException = context.getException();
            if (jobException != null) {
                String errorMessage = jobException.getMessage();
                if (errorMessage != null && errorMessage.length() > 255) {
                    errorMessage = errorMessage.substring(0, 255);
                }
                jobLog.Error__c = errorMessage;
            }
        }

        insert jobLog;

        if (!succeeded && attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
