public without sharing class OpportunityPipelineHandler {
    public static void recalculate(
        List<Opportunity> newRecords,
        List<Opportunity> oldRecords
    ) {
        Set<Id> accountIds = new Set<Id>();

        if (newRecords != null) {
            for (Opportunity opportunity : newRecords) {
                if (opportunity.AccountId != null) {
                    accountIds.add(opportunity.AccountId);
                }
            }
        }

        if (oldRecords != null) {
            for (Opportunity opportunity : oldRecords) {
                if (opportunity.AccountId != null) {
                    accountIds.add(opportunity.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> amountsByAccountId = new Map<Id, Decimal>();
        Map<Id, Integer> countsByAccountId = new Map<Id, Integer>();

        for (AggregateResult result : [
            SELECT AccountId accountId, SUM(Amount) totalAmount, COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');
            Decimal totalAmount = (Decimal) result.get('totalAmount');

            amountsByAccountId.put(
                accountId,
                totalAmount == null ? 0 : totalAmount
            );
            countsByAccountId.put(accountId, (Integer) result.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Account account : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal totalAmount = amountsByAccountId.containsKey(account.Id)
                ? amountsByAccountId.get(account.Id)
                : 0;
            Integer openCount = countsByAccountId.containsKey(account.Id)
                ? countsByAccountId.get(account.Id)
                : 0;

            if (account.FB_Open_Pipeline__c != totalAmount
                || account.FB_Open_Opportunities__c != openCount) {
                account.FB_Open_Pipeline__c = totalAmount;
                account.FB_Open_Opportunities__c = openCount;
                accountsToUpdate.add(account);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
