public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<FB_Integration_Log__c> {
    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        Database.executeBatch(this, 200);
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        Datetime regularCutoff = Datetime.now().addDays(-30);

        return Database.getQueryLocator([
            SELECT Id, Level__c, CreatedDate
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :regularCutoff
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<FB_Integration_Log__c> scope
    ) {
        Datetime errorCutoff = Datetime.now().addDays(-180);
        List<FB_Integration_Log__c> logsToDelete = new List<FB_Integration_Log__c>();

        for (FB_Integration_Log__c logRecord : scope) {
            if (logRecord.Level__c == 'ERROR') {
                if (logRecord.CreatedDate < errorCutoff) {
                    logsToDelete.add(logRecord);
                }
            } else {
                logsToDelete.add(logRecord);
            }
        }

        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }

    public void finish(Database.BatchableContext context) {
    }

    public static Id scheduleNightly() {
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
