public class Opportunities extends fflib_SObjectDomain {
    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void onAfterInsert() {
        Set<Id> qualifyingOpportunityIds = new Set<Id>();

        for (Opportunity opportunityRecord : (List<Opportunity>) Records) {
            if (opportunityRecord.StageName == 'Closed Won') {
                qualifyingOpportunityIds.add(opportunityRecord.Id);
            }
        }

        startFulfilmentIfNeeded(qualifyingOpportunityIds);
    }

    public override void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Map<Id, Opportunity> oldOpportunities =
            (Map<Id, Opportunity>) existingRecords;
        Set<Id> qualifyingOpportunityIds = new Set<Id>();

        for (Opportunity opportunityRecord : (List<Opportunity>) Records) {
            Opportunity oldOpportunity = oldOpportunities.get(opportunityRecord.Id);

            if (opportunityRecord.StageName == 'Closed Won'
                && oldOpportunity.StageName != 'Closed Won') {
                qualifyingOpportunityIds.add(opportunityRecord.Id);
            }
        }

        startFulfilmentIfNeeded(qualifyingOpportunityIds);
    }

    private static void startFulfilmentIfNeeded(Set<Id> opportunityIds) {
        if (!opportunityIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                (IOpportunityFulfilmentService) Application.Service.newInstance(
                    IOpportunityFulfilmentService.class
                );
            service.startFulfilment(opportunityIds);
        }
    }
}
