public with sharing class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();
        List<Contact> contactsToUpdate = new List<Contact>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        for (Contact contactRecord : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            if (contactRecord.Phone != null) {
                contactRecord.Phone = contactRecord.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(contactRecord);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            Database.SaveResult[] saveResults = Database.update(contactsToUpdate, false);

            for (Integer i = 0; i < saveResults.size(); i++) {
                if (!saveResults[i].isSuccess()) {
                    errorsByContactId.put(
                        contactsToUpdate[i].Id,
                        saveResults[i].getErrors()[0].getMessage()
                    );
                }
            }
        }

        return errorsByContactId;
    }
}
