public with sharing class PipelineSummary {
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        List<String> stages = new List<String>{
            'Prospecting',
            'Qualification',
            'Proposal/Price Quote',
            'Negotiation/Review'
        };

        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : stages) {
            totals.put(stage, 0);
        }

        // A single grouped aggregate query is simpler and uses fewer queries
        // than running one query for each stage.
        for (AggregateResult result : [
            SELECT StageName, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :stages
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            GROUP BY StageName
        ]) {
            Decimal amount = (Decimal) result.get('totalAmount');
            totals.put(
                (String) result.get('StageName'),
                amount == null ? 0 : amount
            );
        }

        return totals;
    }
}
