public class ErpCustomerSync implements Queueable, Database.AllowsCallouts {
    private static final Integer MAX_CALLOUTS_PER_EXECUTION = 100;

    private class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;
    }

    private List<CustomerPayload> customers;
    private Integer nextIndex;

    public ErpCustomerSync(List<Account> accounts) {
        customers = new List<CustomerPayload>();

        for (Account account : accounts) {
            CustomerPayload customer = new CustomerPayload();
            customer.salesforceId = String.valueOf(account.Id);
            customer.name = account.Name;
            customer.country = String.isBlank(account.BillingCountry)
                ? null
                : account.BillingCountry;
            customers.add(customer);
        }

        nextIndex = 0;
    }

    private ErpCustomerSync(List<CustomerPayload> customers, Integer nextIndex) {
        this.customers = customers;
        this.nextIndex = nextIndex;
    }

    public void execute(QueueableContext context) {
        Integer endIndex = nextIndex + MAX_CALLOUTS_PER_EXECUTION;
        if (endIndex > customers.size()) {
            endIndex = customers.size();
        }

        for (Integer i = nextIndex; i < endIndex; i++) {
            HttpRequest request = new HttpRequest();
            request.setEndpoint('callout:ERP/api/customers');
            request.setMethod('POST');
            request.setHeader('Content-Type', 'application/json');
            request.setBody(JSON.serialize(
                new List<CustomerPayload>{ customers[i] }
            ));

            // Each account is sent in its own request. Response handling and retries
            // are outside the scope of this ticket.
            new Http().send(request);
        }

        // Triggers cannot make callouts directly. Process at most 100 callouts in
        // this Queueable transaction, then chain the remainder to support batches
        // of up to 200 accounts.
        if (endIndex < customers.size()) {
            System.enqueueJob(new ErpCustomerSync(customers, endIndex));
        }
    }
}
