    public static List<Database.SaveResult> publishStageChanges(
        List<Opportunity> opportunities
    ) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> eventsToPublish =
            new List<Deal_Stage_Change__e>();

        for (Opportunity opportunity : opportunities) {
            eventsToPublish.add(new Deal_Stage_Change__e(
                Opportunity_Id__c = String.valueOf(opportunity.Id),
                Stage__c = opportunity.StageName,
                Amount__c = opportunity.Amount
            ));
        }

        // Deviation: publish the events in one bulk call rather than calling
        // EventBus.publish once per opportunity. This avoids consuming a
        // publish/DML call for every record while returning one result per
        // event in input order.
        results.addAll(EventBus.publish(eventsToPublish));
        return results;
    }
}
