public without sharing class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds == null ? new List<Id>() : new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        Id currentCaseId = caseIds[0];

        try {
            List<Case> cases = [
                SELECT CaseNumber, ContactId
                FROM Case
                WHERE Id = :currentCaseId
                LIMIT 1
            ];

            if (!cases.isEmpty() && cases[0].ContactId != null) {
                Case currentCase = cases[0];
                Task surveyTask = new Task(
                    WhatId = currentCase.Id,
                    WhoId = currentCase.ContactId,
                    Subject = 'CSAT survey: ' + currentCase.CaseNumber,
                    ActivityDate = Date.today().addDays(2),
                    Status = 'Not Started'
                );

                Database.SaveResult result = Database.insert(surveyTask, false);
                if (!result.isSuccess()) {
                    for (Database.Error error : result.getErrors()) {
                        System.debug(
                            LoggingLevel.ERROR,
                            'Failed to create CSAT survey task for Case ' +
                            currentCase.Id + ': ' + error.getMessage()
                        );
                    }
                }
            }
        } catch (Exception error) {
            System.debug(
                LoggingLevel.ERROR,
                'Failed to process CSAT survey for Case ' + currentCaseId +
                ': ' + error.getMessage() + '\n' + error.getStackTraceString()
            );
        } finally {
            if (caseIds.size() > 1) {
                List<Id> remainingCaseIds = new List<Id>();
                for (Integer i = 1; i < caseIds.size(); i++) {
                    remainingCaseIds.add(caseIds[i]);
                }
                System.enqueueJob(new CaseSurveyJob(remainingCaseIds));
            }
        }
    }
}
