public with sharing class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> requestedIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                requestedIds.add(opportunityId);
            }
        }

        if (requestedIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId, CloseDate
            FROM Opportunity
            WHERE Id IN :requestedIds
        ];

        if (opportunities.isEmpty()) {
            return 0;
        }

        List<Messaging.Email> emails = new List<Messaging.Email>();
        for (Opportunity opportunity : opportunities) {
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opportunity.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opportunity.Name);
            email.setPlainTextBody(
                'The renewal opportunity is due. Close date: ' +
                String.valueOf(opportunity.CloseDate)
            );
            emails.add(email);
        }

        // Send as one invocation: Apex limits sendEmail invocations per transaction.
        // allOrNothing=false lets individual results succeed or fail independently.
        List<Messaging.SendEmailResult> results = Messaging.sendEmail(emails, false);

        Integer successfulCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successfulCount++;
            }
        }

        return successfulCount;
    }
}
