```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage = '';

    debounceTimeout;
    requestSequence = 0;

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        // Invalidate any in-flight response as soon as the input changes.
        this.requestSequence += 1;
        const currentSequence = this.requestSequence;

        clearTimeout(this.debounceTimeout);
        this.debounceTimeout = undefined;
        this.errorMessage = '';

        if (searchTerm.length < 2) {
            this.contacts = [];
            return;
        }

        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = undefined;

            if (!this.isConnected) {
                return;
            }

            searchContacts({ searchTerm })
                .then((results) => {
                    if (this.isConnected && currentSequence === this.requestSequence) {
                        this.contacts = results || [];
                    }
                })
                .catch((error) => {
                    if (this.isConnected && currentSequence === this.requestSequence) {
                        this.contacts = [];
                        this.errorMessage = error?.body?.message || '';
                    }
                });
        }, DEBOUNCE_DELAY);
    }

    disconnectedCallback() {
        clearTimeout(this.debounceTimeout);
        this.debounceTimeout = undefined;

        // Ignore responses from requests that were already in flight.
        this.requestSequence += 1;
    }
}
