import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60_000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    statsLoaded = false;
    errorMessage;

    _pollingId;
    _requestInFlight = false;
    _boundVisibilityChange;

    constructor() {
        super();
        this._boundVisibilityChange = this.handleVisibilityChange.bind(this);
    }

    connectedCallback() {
        document.addEventListener('visibilitychange', this._boundVisibilityChange);

        if (this._pollingId === undefined) {
            this.loadStats();
            this._pollingId = window.setInterval(() => {
                this.loadStats();
            }, REFRESH_INTERVAL_MS);
        }
    }

    disconnectedCallback() {
        document.removeEventListener('visibilitychange', this._boundVisibilityChange);

        if (this._pollingId !== undefined) {
            window.clearInterval(this._pollingId);
            this._pollingId = undefined;
        }
    }

    get hasStats() {
        return this.statsLoaded;
    }

    get hasError() {
        return Boolean(this.errorMessage);
    }

    handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this.loadStats();
        }
    }

    loadStats() {
        if (
            !this.isConnected ||
            document.visibilityState === 'hidden' ||
            this._requestInFlight
        ) {
            return;
        }

        this._requestInFlight = true;

        getQueueStats()
            .then((result) => {
                if (!this.isConnected) {
                    return;
                }

                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.statsLoaded = true;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (!this.isConnected) {
                    return;
                }

                this.errorMessage =
                    error?.body?.message || 'Unable to load queue statistics.';
            })
            .finally(() => {
                this._requestInFlight = false;
            });
    }
}
