import { LightningElement, api } from 'lwc';

let nextInstanceId = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _instanceId;
    _options = [];
    _value;
    _activeIndex = -1;

    constructor() {
        super();
        nextInstanceId += 1;
        this._instanceId = nextInstanceId;
    }

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value)
            ? value.map((option) => ({
                  value: option?.value,
                  label: option?.label
              }))
            : [];

        this._setActiveToSelectionOrFirst();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value;
        this._setActiveToSelectionOrFirst();
    }

    get renderedOptions() {
        return this._options.map((option, index) => ({
            ...option,
            id: `status-listbox-${this._instanceId}-option-${index}`,
            index,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeOptionId() {
        const activeOption = this.renderedOptions[this._activeIndex];
        return activeOption ? activeOption.id : '';
    }

    _setActiveToSelectionOrFirst() {
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );

        this._activeIndex =
            selectedIndex >= 0 ? selectedIndex : this._options.length > 0 ? 0 : -1;
    }

    handleKeydown(event) {
        const lastIndex = this._options.length - 1;

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                if (lastIndex >= 0) {
                    this._activeIndex = Math.min(
                        Math.max(this._activeIndex, 0) + 1,
                        lastIndex
                    );
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (lastIndex >= 0) {
                    this._activeIndex = Math.max(
                        Math.max(this._activeIndex, 0) - 1,
                        0
                    );
                }
                break;
            case 'Home':
                event.preventDefault();
                if (lastIndex >= 0) {
                    this._activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (lastIndex >= 0) {
                    this._activeIndex = lastIndex;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this._selectIndex(this._activeIndex);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        this._selectIndex(Number(event.currentTarget.dataset.index));
    }

    _selectIndex(index) {
        if (!Number.isInteger(index) || index < 0 || index >= this._options.length) {
            return;
        }

        this._activeIndex = index;

        const selectedOption = this._options[index];
        if (selectedOption.value === this._value) {
            return;
        }

        this._value = selectedOption.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: selectedOption.value }
            })
        );
    }
}
