        return this._tasks;
    }

    set tasks(value) {
        const copiedTasks = Array.isArray(value)
            ? value.map((task) => ({ ...task }))
            : [];

        this._tasks = copiedTasks;
        this.items = copiedTasks.map((task) => ({ ...task }));
    }

    items = [];
    newLabel = '';
    nextId = 1;

    get headingDisplay() {
        return String(this.heading ?? '').toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }

        let id;
        do {
            id = `new-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === id));

        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.currentTarget.dataset.id;
        const checked = event.currentTarget.checked;

        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: checked } : task
        );
    }
}
