public with sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        Set<Id> employerIds = new Set<Id>();

        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (contactId != null && employerId != null) {
                contactIds.add(contactId);
                employerIds.add(employerId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        if (contactsById.isEmpty()) {
            return;
        }

        // Load existing affiliations for the requested organizations and any
        // current primary affiliations. NPSP handles retiring the old primary
        // affiliation when a new affiliation is marked primary.
        List<npe5__Affiliation__c> affiliations = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c,
                   npe5__Status__c, npe5__Primary__c,
                   npe5__StartDate__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactsById.keySet()
              AND (
                  npe5__Organization__c IN :employerIds
                  OR npe5__Primary__c = TRUE
              )
            ORDER BY npe5__Primary__c DESC, LastModifiedDate DESC
        ];

        Map<Id, Map<Id, npe5__Affiliation__c>> targetAffiliationByContactAndOrg =
            new Map<Id, Map<Id, npe5__Affiliation__c>>();

        for (npe5__Affiliation__c affiliation : affiliations) {
            if (!employerIds.contains(affiliation.npe5__Organization__c)) {
                continue;
            }

            Id contactId = affiliation.npe5__Contact__c;
            Id employerId = affiliation.npe5__Organization__c;

            if (!targetAffiliationByContactAndOrg.containsKey(contactId)) {
                targetAffiliationByContactAndOrg.put(
                    contactId,
                    new Map<Id, npe5__Affiliation__c>()
                );
            }

            Map<Id, npe5__Affiliation__c> affiliationsByOrg =
                targetAffiliationByContactAndOrg.get(contactId);

            if (!affiliationsByOrg.containsKey(employerId)) {
                affiliationsByOrg.put(employerId, affiliation);
            }
        }

        Date today = Date.today();
        List<npe5__Affiliation__c> affiliationsToUpdate =
            new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert =
            new List<npe5__Affiliation__c>();

        for (Id contactId : contactsById.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (employerId == null) {
                continue;
            }

            Contact contact = contactsById.get(contactId);

            // If NPSP already identifies this organization as primary, leave
            // the existing affiliation unchanged.
            if (contact.npsp__Primary_Affiliation__c == employerId) {
                continue;
            }

            npe5__Affiliation__c targetAffiliation;
            Map<Id, npe5__Affiliation__c> affiliationsByOrg =
                targetAffiliationByContactAndOrg.get(contactId);

            if (affiliationsByOrg != null) {
                targetAffiliation = affiliationsByOrg.get(employerId);
            }

            if (targetAffiliation == null) {
                affiliationsToInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = employerId,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today
                ));
            } else {
                if (targetAffiliation.npe5__Status__c == 'Former'
                    || targetAffiliation.npe5__StartDate__c == null) {
                    targetAffiliation.npe5__StartDate__c = today;
                }

                targetAffiliation.npe5__Status__c = 'Current';
                targetAffiliation.npe5__Primary__c = true;
                targetAffiliation.npe5__EndDate__c = null;
                affiliationsToUpdate.add(targetAffiliation);
            }
        }

        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }
}
