public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException('Each GAU percentage must be greater than zero.');
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException('GAU allocation percentages cannot exceed 100%.');
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('The specified opportunity does not exist.');
        }
        Opportunity opportunity = opportunities[0];

        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gausById =
            new Map<Id, npsp__General_Accounting_Unit__c>([
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]);

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null || gau.npsp__Active__c != true) {
                throw new AllocationException('Every GAU must exist and be active.');
            }
        }

        Decimal opportunityAmount = opportunity.Amount == null ? 0 : opportunity.Amount;
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunity.Id,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent,
                npsp__Amount__c = opportunityAmount * percent / 100
            ));
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunity.Id
        ];

        Savepoint savepoint = Database.setSavepoint();
        try {
            if (!existingAllocations.isEmpty()) {
                delete existingAllocations;
            }
            insert newAllocations;
        } catch (Exception e) {
            Database.rollback(savepoint);
            throw e;
        }

        return newAllocations;
    }
}
