public with sharing class HouseholdService {
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('At least one contact is required.');
        }

        Savepoint savepoint = Database.setSavepoint();

        try {
            // NPSP creates and names a household when a contact is inserted
            // without an AccountId. Insert only the first contact this way.
            Contact primaryMember = members[0];
            insert primaryMember;

            // Read the AccountId NPSP assigned to the first contact.
            Contact persistedPrimary = [
                SELECT AccountId
                FROM Contact
                WHERE Id = :primaryMember.Id
                LIMIT 1
            ];
            Id householdId = persistedPrimary.AccountId;

            // Associate the rest of the family with that same household.
            List<Contact> additionalMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i];
                member.AccountId = householdId;
                additionalMembers.add(member);
            }

            if (!additionalMembers.isEmpty()) {
                insert additionalMembers;
            }

            // Set the household's primary contact without setting its Name;
            // NPSP remains responsible for household naming and greetings.
            update new Account(
                Id = householdId,
                npe01__One2OneContact__c = primaryMember.Id
            );

            return householdId;
        } catch (Exception e) {
            Database.rollback(savepoint);
            throw e;
        }
    }
}
