public with sharing class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('The number of payments must be at least 1.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        List<Opportunity> opportunities = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            FOR UPDATE
        ];
        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('The opportunity could not be found.');
        }

        Opportunity opportunityRecord = opportunities[0];
        if (opportunityRecord.IsClosed) {
            throw new PaymentPlanException('Installments cannot be scheduled for a closed opportunity.');
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            FOR UPDATE
        ];

        Decimal outstandingAmount = opportunityRecord.Amount == null
            ? 0
            : opportunityRecord.Amount;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c existingPayment : existingPayments) {
            Boolean isPaid = existingPayment.npe01__Paid__c == true;
            Boolean isWrittenOff = existingPayment.npe01__Written_Off__c == true;

            if (isPaid || isWrittenOff) {
                if (existingPayment.npe01__Payment_Amount__c != null) {
                    outstandingAmount -= existingPayment.npe01__Payment_Amount__c;
                }
            } else {
                paymentsToDelete.add(existingPayment);
            }
        }

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('The outstanding amount must be greater than zero.');
        }

        Decimal installmentAmount =
            (outstandingAmount / numberOfPayments).setScale(2, RoundingMode.DOWN);
        List<npe01__OppPayment__c> paymentsToInsert =
            new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal paymentAmount = i == numberOfPayments - 1
                ? outstandingAmount - (installmentAmount * (numberOfPayments - 1))
                : installmentAmount;

            paymentsToInsert.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = paymentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        Savepoint savepoint = Database.setSavepoint();
        try {
            if (!paymentsToDelete.isEmpty()) {
                delete paymentsToDelete;
            }
            insert paymentsToInsert;
        } catch (Exception e) {
            Database.rollback(savepoint);
            throw e;
        }

        return paymentsToInsert;
    }
}
