public with sharing class GiftService {
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be greater than zero.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact must belong to a household account.');
        }

        String firstName = donor.FirstName == null ? '' : donor.FirstName.trim();
        String lastName = donor.LastName == null ? '' : donor.LastName.trim();
        String giftName = (firstName + ' ' + lastName).trim()
            + ' Donation ' + formatDate(giftDate);

        Opportunity gift = new Opportunity(
            Name = giftName,
            AccountId = donor.AccountId,
            StageName = 'Closed Won',
            CloseDate = giftDate,
            Amount = amount,
            npsp__Primary_Contact__c = donor.Id
        );
        insert gift;

        reconcileContactRoles(gift.Id, donor);
        reconcilePayments(gift.Id, amount, giftDate);

        return gift.Id;
    }

    private static void reconcileContactRoles(Id opportunityId, Contact donor) {
        Map<Id, String> desiredRoles = new Map<Id, String>{
            donor.Id => 'Donor'
        };

        for (Contact householdMember : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ]) {
            desiredRoles.put(
                householdMember.Id,
                householdMember.Id == donor.Id ? 'Donor' : 'Household Member'
            );
        }

        Map<Id, OpportunityContactRole> retainedByContact =
            new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> duplicatesOrUnwanted =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole existingRole : [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ]) {
            if (existingRole.ContactId == null
                || !desiredRoles.containsKey(existingRole.ContactId)
                || retainedByContact.containsKey(existingRole.ContactId)) {
                duplicatesOrUnwanted.add(existingRole);
            } else {
                retainedByContact.put(existingRole.ContactId, existingRole);
            }
        }

        if (!duplicatesOrUnwanted.isEmpty()) {
            delete duplicatesOrUnwanted;
        }

        List<OpportunityContactRole> rolesToUpdate =
            new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToInsert =
            new List<OpportunityContactRole>();

        for (Id contactId : desiredRoles.keySet()) {
            String desiredRole = desiredRoles.get(contactId);
            Boolean isPrimary = contactId == donor.Id;

            if (retainedByContact.containsKey(contactId)) {
                OpportunityContactRole existingRole = retainedByContact.get(contactId);
                existingRole.Role = desiredRole;
                existingRole.IsPrimary = isPrimary;
                rolesToUpdate.add(existingRole);
            } else {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = contactId,
                    Role = desiredRole,
                    IsPrimary = isPrimary
                ));
            }
        }

        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    private static void reconcilePayments(
        Id opportunityId,
        Decimal amount,
        Date giftDate
    ) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        npe01__OppPayment__c payment;
        List<npe01__OppPayment__c> duplicatePayments =
            new List<npe01__OppPayment__c>();

        if (existingPayments.isEmpty()) {
            payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId
            );
        } else {
            payment = existingPayments[0];
            for (Integer i = 1; i < existingPayments.size(); i++) {
                duplicatePayments.add(existingPayments[i]);
            }
        }

        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;

        if (!duplicatePayments.isEmpty()) {
            delete duplicatePayments;
        }

        if (existingPayments.isEmpty()) {
            insert payment;
        } else {
            update payment;
        }
    }

    private static String formatDate(Date value) {
        return String.valueOf(value.year())
            + '-' + twoDigits(value.month())
            + '-' + twoDigits(value.day());
    }

    private static String twoDigits(Integer value) {
        return value < 10
            ? '0' + String.valueOf(value)
            : String.valueOf(value);
    }
}
