public without sharing class FamilyService {
    /**
     * Creates a Parent relationship for each child/parent pair that does not
     * already have a relationship in either direction. With NPSP's List
     * Setting reciprocal method, NPSP creates and links the reciprocal record
     * using the configured Relationship Lookup.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        List<npe4__Relationship__c> candidates =
            new List<npe4__Relationship__c>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> requestedPairKeys = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String key = pairKey(childId, parentId);
            if (!requestedPairKeys.add(key)) {
                continue;
            }

            contactIds.add(childId);
            contactIds.add(parentId);
            candidates.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Check all relationships among the contacts in this import. A match
        // in either orientation means the pair must be skipped.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
              AND npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairKeys.add(
                pairKey(existing.npe4__Contact__c, existing.npe4__RelatedContact__c)
            );
        }

        List<npe4__Relationship__c> relationshipsToInsert =
            new List<npe4__Relationship__c>();
        for (npe4__Relationship__c candidate : candidates) {
            if (!existingPairKeys.contains(pairKey(
                candidate.npe4__Contact__c,
                candidate.npe4__RelatedContact__c
            ))) {
                relationshipsToInsert.add(candidate);
            }
        }

        if (!relationshipsToInsert.isEmpty()) {
            insert relationshipsToInsert;
        }
    }

    private static String pairKey(Id firstId, Id secondId) {
        String first = String.valueOf(firstId);
        String second = String.valueOf(secondId);

        if (first.compareTo(second) <= 0) {
            return first + '|' + second;
        }
        return second + '|' + first;
    }
}
