global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper =
            new npsp.TDTM_Runnable.DmlWrapper();

        Map<Id, Opportunity> oldOpportunitiesById = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject oldRecord : oldlist) {
                Opportunity oldOpportunity = (Opportunity) oldRecord;
                oldOpportunitiesById.put(oldOpportunity.Id, oldOpportunity);
            }
        }

        List<Task> tasksToInsert = new List<Task>();
        if (newlist != null) {
            for (SObject newRecord : newlist) {
                Opportunity opportunity = (Opportunity) newRecord;

                if (!isMajorGiftWon(opportunity)) {
                    continue;
                }

                Opportunity oldOpportunity = opportunity.Id == null
                    ? null
                    : oldOpportunitiesById.get(opportunity.Id);

                if (oldOpportunity != null && isMajorGiftWon(oldOpportunity)) {
                    continue;
                }

                tasksToInsert.add(new Task(
                    Subject = 'Major gift thank-you call',
                    Priority = 'High',
                    Status = 'Not Started',
                    WhatId = opportunity.Id,
                    WhoId = opportunity.npsp__Primary_Contact__c,
                    OwnerId = opportunity.OwnerId,
                    ActivityDate = opportunity.CloseDate.addDays(3)
                ));
            }
        }

        dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        return dmlWrapper;
    }

    private static Boolean isMajorGiftWon(Opportunity opportunity) {
        return opportunity != null
            && opportunity.StageName == 'Closed Won'
            && opportunity.Amount != null
            && opportunity.Amount >= 5000;
    }
}
