public with sharing class RecordAccessService {
    private static final Integer USER_RECORD_ACCESS_BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        List<Id> idsToCheck = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                idsToCheck.add(recordId);
            }
        }

        Id runningUserId = UserInfo.getUserId();

        for (
            Integer offset = 0;
            offset < idsToCheck.size();
            offset += USER_RECORD_ACCESS_BATCH_SIZE
        ) {
            List<Id> batchIds = new List<Id>();
            Integer endIndex = offset + USER_RECORD_ACCESS_BATCH_SIZE;
            if (endIndex > idsToCheck.size()) {
                endIndex = idsToCheck.size();
            }

            for (Integer index = offset; index < endIndex; index++) {
                batchIds.add(idsToCheck[index]);
            }

            for (UserRecordAccess accessRecord : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                AND RecordId IN :batchIds
            ]) {
                if (accessRecord.HasEditAccess) {
                    editableRecordIds.add(accessRecord.RecordId);
                }
            }
        }

        return editableRecordIds;
    }
}
