public without sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Account> accounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :accountIds
        ];
        List<Contact> contacts = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];

        if (accounts.isEmpty() && contacts.isEmpty()) {
            return;
        }

        TriggerBase.bypass(Account.SObjectType);
        try {
            if (!accounts.isEmpty()) {
                for (Account account : accounts) {
                    account.OwnerId = newOwnerId;
                }
                update accounts;
            }

            if (!contacts.isEmpty()) {
                for (Contact contact : contacts) {
                    contact.OwnerId = newOwnerId;
                }
                update contacts;
            }
        } finally {
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
