@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    @IsTest
    static void rejectsReductionOfMoreThanHalf() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpportunity = new Opportunity(Id = opportunityId, Amount = 1000);
        Opportunity newOpportunity = new Opportunity(Id = opportunityId, Amount = 499);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpportunity },
            new List<Opportunity>{ oldOpportunity }
        );

        System.assert(newOpportunity.hasErrors(), 'A reduction of more than half should be rejected.');
        List<Database.Error> errors = newOpportunity.getErrors();
        System.assertEquals(1, errors.size(), 'The record should receive exactly one error.');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'The error should match the action message.'
        );
    }

    @IsTest
    static void acceptsHalfReductionAndIncrease() {
        Id halfReductionId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id increaseId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldHalfReduction = new Opportunity(Id = halfReductionId, Amount = 1000);
        Opportunity newHalfReduction = new Opportunity(Id = halfReductionId, Amount = 500);
        Opportunity oldIncrease = new Opportunity(Id = increaseId, Amount = 1000);
        Opportunity newIncrease = new Opportunity(Id = increaseId, Amount = 1500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newHalfReduction, newIncrease },
            new List<Opportunity>{ oldHalfReduction, oldIncrease }
        );

        System.assert(!newHalfReduction.hasErrors(), 'A reduction of exactly half should be accepted.');
        System.assertEquals(0, newHalfReduction.getErrors().size());
        System.assert(!newIncrease.hasErrors(), 'An increase should be accepted.');
        System.assertEquals(0, newIncrease.getErrors().size());
    }

    @IsTest
    static void acceptsWhenPreviousAmountIsNull() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpportunity = new Opportunity(Id = opportunityId, Amount = null);
        Opportunity newOpportunity = new Opportunity(Id = opportunityId, Amount = 100);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpportunity },
            new List<Opportunity>{ oldOpportunity }
        );

        System.assert(!newOpportunity.hasErrors(), 'A null previous Amount should be accepted.');
        System.assertEquals(0, newOpportunity.getErrors().size());
    }

    @IsTest
    static void addsErrorsOnlyToRecordsThatBreakTheRule() {
        Id rejectedId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id boundaryId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id increaseId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldRejected = new Opportunity(Id = rejectedId, Amount = 1000);
        Opportunity newRejected = new Opportunity(Id = rejectedId, Amount = 499);
        Opportunity oldBoundary = new Opportunity(Id = boundaryId, Amount = 1000);
        Opportunity newBoundary = new Opportunity(Id = boundaryId, Amount = 500);
        Opportunity oldIncrease = new Opportunity(Id = increaseId, Amount = 1000);
        Opportunity newIncrease = new Opportunity(Id = increaseId, Amount = 1200);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newRejected, newBoundary, newIncrease },
            new List<Opportunity>{ oldRejected, oldBoundary, oldIncrease }
        );

        System.assert(newRejected.hasErrors(), 'The record violating the rule should have an error.');
        List<Database.Error> rejectedErrors = newRejected.getErrors();
        System.assertEquals(1, rejectedErrors.size(), 'Only one error should be added to the violating record.');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            rejectedErrors[0].getMessage()
        );

        System.assert(!newBoundary.hasErrors(), 'The boundary record should have no errors.');
        System.assertEquals(0, newBoundary.getErrors().size());
        System.assert(!newIncrease.hasErrors(), 'The increase record should have no errors.');
        System.assertEquals(0, newIncrease.getErrors().size());
    }
}
