public without sharing class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert,
               TriggerAction.AfterUpdate,
               TriggerAction.AfterDelete,
               TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculateAccountCounts(getAccountIds(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];

            if (newCase.AccountId != oldCase.AccountId ||
                newCase.IsClosed != oldCase.IsClosed) {
                addAccountId(accountIds, oldCase.AccountId);
                addAccountId(accountIds, newCase.AccountId);
            }
        }

        recalculateAccountCounts(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculateAccountCounts(getAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculateAccountCounts(getAccountIds(triggerNew));
    }

    private static Set<Id> getAccountIds(List<SObject> cases) {
        Set<Id> accountIds = new Set<Id>();

        for (SObject record : cases) {
            addAccountId(accountIds, ((Case) record).AccountId);
        }

        return accountIds;
    }

    private static void addAccountId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    private static void recalculateAccountCounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // Lock parent rows before recounting so concurrent case changes for the same
        // accounts serialize before reading and writing the count.
        List<Account> accounts = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ];

        if (accounts.isEmpty()) {
            return;
        }

        Set<Id> existingAccountIds = new Set<Id>();
        for (Account account : accounts) {
            existingAccountIds.add(account.Id);
        }

        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult result : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :existingAccountIds
                AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCountByAccountId.put(
                (Id) result.get('AccountId'),
                (Integer) result.get('openCount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account account : accounts) {
            Integer openCount = openCountByAccountId.containsKey(account.Id)
                ? openCountByAccountId.get(account.Id)
                : 0;
            Decimal expectedCount = Decimal.valueOf(openCount);

            if (account.FB_Open_Case_Count__c != expectedCount) {
                accountsToUpdate.add(new Account(
                    Id = account.Id,
                    FB_Open_Case_Count__c = expectedCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
